def poly(x, d):
    from itertools import combinations_with_replacement as comb
    return np.stack([np.prod(x[:, i], axis=1) for j in range(d + 1) for i in comb(range(x.shape[1]), j)], 1)

def loo(A, b):
    P = np.linalg.pinv(A)
    r = b - A @ (P @ b)
    d = np.maximum(1 - np.sum(A * P.T, 1), 1e-10)
    return np.sqrt(np.mean((r / d[:, None]) ** 2))
